#!/usr/bin/env bash
# Build the owenclave desktop proxy core (libexclavecore JNI + exclave-core CLI)
# for desktop platforms.
#
# On desktop we build:
# 1. `libgojni.so` / `gojni.dll` / `libgojni.dylib` — the native JNI library for
#    `github.com/exclavenetwork/libexclavecore` (generated by `gobind`), so the
#    desktop app calls the exact same Go methods (`V2RayInstance`, `Tun2ray`,
#    `STUNClient`, `CertProber`, `HTTPClient`, `urlTest`, etc.) 1-to-1 with Android.
# 2. `owenclave-core(.exe)` — the standalone CLI binary used by CLI tools/tests.
#
# Usage:
#   ./run desktop core build                 # host platform only
#   TARGETS="windows/amd64" ./run desktop core build
#   ./run desktop core build all             # every supported target
set -euo pipefail

PROJECT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"

OUT_ROOT="${OUT_ROOT:-$PROJECT/desktop/core/dist}"
CORE_PKG="github.com/exclavenetwork/exclave-core/v5/main"
LIB_PKG="github.com/exclavenetwork/libexclavecore"
LDFLAGS="-s -w -buildid="

host_os="$(go env GOOS)"
host_arch="$(go env GOARCH)"
default_targets="$host_os/$host_arch"

if [ "${1:-}" = "all" ]; then
  default_targets="linux/amd64 linux/arm64 darwin/amd64 darwin/arm64 windows/amd64 windows/arm64"
fi

TARGETS="${TARGETS:-$default_targets}"

export PATH="$(go env GOPATH)/bin:$PATH"
JAVA_HOME="${JAVA_HOME:-/usr/lib/jvm/java-21-openjdk}"

prepend_line() {
  local line="$1"
  local file="$2"
  local tmp="${file}.tmp"
  { printf '%s\n\n' "$line"; cat "$file"; } > "$tmp"
  mv "$tmp" "$file"
}

build_gojni() {
  local target_os="$1"
  local target_arch="$2"
  local out_dir="$3"

  local lib_name=""
  local cc_bin=""
  local ar_bin="ar"
  local strip_bin="strip"
  case "$target_os/$target_arch" in
    linux/amd64)
      lib_name="libgojni.so"
      cc_bin="${CC_LINUX_AMD64:-gcc}"
      ;;
    linux/arm64)
      lib_name="libgojni.so"
      if [ "$host_os/$host_arch" = "linux/arm64" ]; then
        cc_bin="gcc"
      elif command -v aarch64-linux-gnu-gcc >/dev/null 2>&1; then
        cc_bin="aarch64-linux-gnu-gcc"
        ar_bin="aarch64-linux-gnu-ar"
        strip_bin="aarch64-linux-gnu-strip"
      else
        echo "    (skipping JNI $lib_name for $target_os/$target_arch: aarch64-linux-gnu-gcc not installed)"
        return 0
      fi
      ;;
    windows/amd64)
      lib_name="gojni.dll"
      if [ "$host_os" = "windows" ]; then
        cc_bin="gcc"
      elif command -v x86_64-w64-mingw32-gcc >/dev/null 2>&1; then
        cc_bin="x86_64-w64-mingw32-gcc"
        ar_bin="x86_64-w64-mingw32-ar"
        strip_bin="x86_64-w64-mingw32-strip"
      else
        echo "    (skipping JNI $lib_name for $target_os/$target_arch: x86_64-w64-mingw32-gcc not installed)"
        return 0
      fi
      ;;
    darwin/*)
      lib_name="libgojni.dylib"
      if [ "$host_os" = "darwin" ]; then
        cc_bin="clang"
      else
        echo "    (skipping JNI $lib_name for $target_os/$target_arch: requires macOS host)"
        return 0
      fi
      ;;
    *)
      return 0
      ;;
  esac

  if ! command -v gobind >/dev/null 2>&1; then
    echo ">>> installing gobind"
    (cd "$PROJECT/library/core" && go install golang.org/x/mobile/cmd/gobind@v0.0.0-20261011034528-197770444867) || true
  fi
  if ! command -v gobind >/dev/null 2>&1; then
    echo "    (skipping JNI $lib_name: gobind not found in PATH)"
    return 0
  fi

  echo ">>> building JNI libexclavecore ($lib_name) for $target_os/$target_arch"
  local raw_work_dir="$PROJECT/library/core/.gobind-work-${target_os}-${target_arch}"
  rm -rf "$raw_work_dir"
  mkdir -p "$raw_work_dir"
  trap "rm -rf '$raw_work_dir'" RETURN

  local work_dir="$raw_work_dir"
  local java_home_dir="$JAVA_HOME"
  local out_dir_norm="$out_dir"
  if command -v cygpath >/dev/null 2>&1; then
    work_dir="$(cygpath -m "$raw_work_dir")"
    java_home_dir="$(cygpath -m "$JAVA_HOME")"
    out_dir_norm="$(cygpath -m "$out_dir")"
  fi

  (cd "$PROJECT/library/core" && gobind -lang=go,java -outdir="$work_dir" "$LIB_PKG")

  mkdir -p "$raw_work_dir/include/android" "$raw_work_dir/lib"
  cat << 'HEADER' > "$raw_work_dir/include/android/log.h"
#ifndef _ANDROID_LOG_H
#define _ANDROID_LOG_H
#include <stdio.h>
#include <stdarg.h>
enum {
    ANDROID_LOG_UNKNOWN = 0,
    ANDROID_LOG_DEFAULT,
    ANDROID_LOG_VERBOSE,
    ANDROID_LOG_DEBUG,
    ANDROID_LOG_INFO,
    ANDROID_LOG_WARN,
    ANDROID_LOG_ERROR,
    ANDROID_LOG_FATAL,
    ANDROID_LOG_SILENT,
};
static inline int __android_log_write(int prio, const char *tag, const char *text) {
    return fprintf(stderr, "[%s] %s\n", tag ? tag : "", text ? text : "");
}
static inline int __android_log_print(int prio, const char *tag, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "[%s] ", tag ? tag : "");
    int r = vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    return r;
}
#endif
HEADER

  "$ar_bin" rcs "$raw_work_dir/lib/liblog.a"
  "$ar_bin" rcs "$raw_work_dir/lib/libandroid.a"

  cp "$PROJECT/library/core/go.mod" "$raw_work_dir/src/gobind/go.mod"
  cp "$PROJECT/library/core/go.sum" "$raw_work_dir/src/gobind/go.sum"

  for f in "$raw_work_dir/src/gobind/"*_android.go; do
    [ -e "$f" ] && mv "$f" "${f%_android.go}_jni.go"
  done
  for f in "$raw_work_dir/src/gobind/"*_android.c; do
    [ -e "$f" ] && mv "$f" "${f%_android.c}_jni.c"
  done

  local cflags="-D__GOBIND_ANDROID__ -Wno-incompatible-pointer-types -I$work_dir/include -I$java_home_dir/include"
  if [ "$target_os" = "linux" ]; then
    cflags="$cflags -I$java_home_dir/include/linux"
  elif [ "$target_os" = "darwin" ]; then
    cflags="$cflags -I$java_home_dir/include/darwin"
  elif [ "$target_os" = "windows" ]; then
    if [ -d "$JAVA_HOME/include/win32" ]; then
      cflags="$cflags -I$java_home_dir/include/win32"
    else
      cat << 'WIN_JNI' > "$raw_work_dir/include/jni_md.h"
#ifndef _JAVASOFT_JNI_MD_H_
#define _JAVASOFT_JNI_MD_H_
#define JNIEXPORT __declspec(dllexport)
#define JNIIMPORT __declspec(dllimport)
#define JNICALL __stdcall
typedef int jint;
typedef long long jlong;
typedef signed char jbyte;
#endif
WIN_JNI
    fi
  fi

  if [ "$target_os" != "linux" ]; then
    local mod_src
    mod_src="$(cd "$PROJECT/library/core" && go list -m -f '{{.Dir}}' "$LIB_PKG")"
    cp -r "$mod_src" "$raw_work_dir/libexclavecore"
    chmod -R u+w "$raw_work_dir/libexclavecore"

    prepend_line "//go:build linux" "$raw_work_dir/libexclavecore/tz.go"
    prepend_line "//go:build linux" "$raw_work_dir/libexclavecore/protect.go"
    cat << 'EOF' > "$raw_work_dir/libexclavecore/protect_nonlinux.go"
//go:build !linux

package libexclavecore

import "io"

func protectServer(path string, protector Protector) io.Closer { return nil }
func protect(path string, fd uintptr) error { return nil }
EOF

    prepend_line "//go:build linux" "$raw_work_dir/libexclavecore/procfs.go"
    cat << 'EOF' > "$raw_work_dir/libexclavecore/procfs_nonlinux.go"
