    perl -pi -e 's|"golang.org/x/sys/unix"|"syscall"|g; s|unix\.IPPROTO_TCP|syscall.IPPROTO_TCP|g; s|unix\.IPPROTO_UDP|syscall.IPPROTO_UDP|g' "$raw_work_dir/libexclavecore/tun.go"

    prepend_line "//go:build linux" "$raw_work_dir/libexclavecore/dialer.go"
    cat << 'EOF' > "$raw_work_dir/libexclavecore/dialer_nonlinux.go"
//go:build !linux

package libexclavecore

import (
	"context"
	"net"
	"syscall"

	"github.com/exclavenetwork/exclave-core/v5/common/errors"
	v2rayNet "github.com/exclavenetwork/exclave-core/v5/common/net"
	"github.com/exclavenetwork/exclave-core/v5/features/dns"
	"github.com/exclavenetwork/exclave-core/v5/transport/internet"
)

var _ internet.SystemDialer = (*protectedDialer)(nil)

type Protector interface {
	Protect(fd int32) bool
}

type noopProtector struct{}

func (n *noopProtector) Protect(int32) bool {
	return true
}

type protectedDialer struct {
	protector Protector
	resolver  func(domain string) ([]net.IP, error)
}

func (dialer protectedDialer) Dial(ctx context.Context, src v2rayNet.Address, dest v2rayNet.Destination, sockopt *internet.SocketConfig) (net.Conn, error) {
	if dest.Network == v2rayNet.Network_Unknown || dest.Network == v2rayNet.Network_UNIX || dest.Address == nil {
		return nil, errors.New("invalid destination")
	}
	if dest.Address.Family().IsDomain() {
		ips, err := dialer.resolver(dest.Address.Domain())
		if err == nil && len(ips) == 0 {
			err = dns.ErrEmptyResponse
		}
		if err != nil {
			return nil, err
		}
		dest.Address = v2rayNet.IPAddress(ips[0])
	}
	control := func(network, address string, c syscall.RawConn) error {
		var ctrlErr error
		err := c.Control(func(fd uintptr) {
			if !dialer.protector.Protect(int32(fd)) {
				ctrlErr = errors.New("protect failed")
				return
			}
			if sockopt != nil {
				internet.ApplySockopt(network, address, fd, sockopt)
			}
		})
		if err != nil {
			return err
		}
		return ctrlErr
	}
	switch dest.Network {
	case v2rayNet.Network_UDP:
		lc := net.ListenConfig{Control: control}
		bindAddr := ":0"
		if src != nil && src != v2rayNet.AnyIP && src != v2rayNet.AnyIPv6 {
			bindAddr = net.JoinHostPort(src.IP().String(), "0")
		}
		packetConn, err := lc.ListenPacket(ctx, "udp", bindAddr)
		if err != nil {
			return nil, err
		}
		destAddr, err := net.ResolveUDPAddr("udp", dest.NetAddr())
		if err != nil {
			packetConn.Close()
			return nil, err
		}
		return &internet.PacketConnWrapper{
			Conn: packetConn,
			Dest: destAddr,
		}, nil
	default:
		d := net.Dialer{Control: control}
		if src != nil && src != v2rayNet.AnyIP && src != v2rayNet.AnyIPv6 {
			d.LocalAddr = &net.TCPAddr{IP: src.IP()}
		}
		return d.DialContext(ctx, "tcp", dest.NetAddr())
	}
}
EOF

