    cat << 'EOF' > "$raw_work_dir/libexclavecore/gvisor/gvisor_nonlinux.go"
//go:build !linux

package gvisor

import (
	"errors"
	"io"
	"math"
	"os"
	"time"

	"github.com/exclavenetwork/exclave-core/v5/common/buf"
	"gvisor.dev/gvisor/pkg/buffer"
	"gvisor.dev/gvisor/pkg/tcpip"
	"gvisor.dev/gvisor/pkg/tcpip/header"
	"gvisor.dev/gvisor/pkg/tcpip/link/channel"
	"gvisor.dev/gvisor/pkg/tcpip/link/sniffer"
	"gvisor.dev/gvisor/pkg/tcpip/network/ipv4"
	"gvisor.dev/gvisor/pkg/tcpip/network/ipv6"
	"gvisor.dev/gvisor/pkg/tcpip/stack"
	"gvisor.dev/gvisor/pkg/tcpip/transport/icmp"
	"gvisor.dev/gvisor/pkg/tcpip/transport/tcp"
	"gvisor.dev/gvisor/pkg/tcpip/transport/udp"

	"github.com/exclavenetwork/libexclavecore/tun"
)

var _ tun.Tun = (*GVisor)(nil)

type GVisor struct {
	endpoint stack.LinkEndpoint
	stack    *stack.Stack
	pcapFile *os.File
}

func (t *GVisor) Close() error {
	t.endpoint.Attach(nil)
	t.stack.Close()
	for _, endpoint := range t.stack.CleanupEndpoints() {
		endpoint.Abort()
	}
	if t.pcapFile != nil {
		go func() {
			time.Sleep(time.Second)
			_ = t.pcapFile.Close()
		}()
	}
	return nil
}

const DefaultNIC tcpip.NICID = 0x01

func newDeviceEndpoint(dev, mtu int32) (stack.LinkEndpoint, error) {
	ep := channel.New(512, uint32(mtu), "")
	device := os.NewFile(uintptr(dev), "tun")
	go func() {
		rawBuf := make([]byte, mtu)
		for {
			n, err := device.Read(rawBuf)
			if err != nil {
				break
			}
			if n == 0 {
				continue
			}
			var proto tcpip.NetworkProtocolNumber
			switch header.IPVersion(rawBuf[:n]) {
			case header.IPv4Version:
				proto = header.IPv4ProtocolNumber
			case header.IPv6Version:
				proto = header.IPv6ProtocolNumber
			default:
				continue
			}
			pkt := stack.NewPacketBuffer(stack.PacketBufferOptions{
				Payload: buffer.MakeWithData(rawBuf[:n]),
			})
			ep.InjectInbound(proto, pkt)
			pkt.DecRef()
		}
	}()
	go func() {
		for {
			pkt := ep.Read()
			if pkt == nil {
				break
			}
			view := pkt.ToView()
			_, _ = device.Write(view.AsSlice())
			view.Release()
			pkt.DecRef()
		}
	}()
	return ep, nil
}

func New(dev, mtu int32, handler tun.Handler, pcapFile *os.File, enableIPv6, discardICMP bool, discardIPv6 func() bool) (*GVisor, error) {
	endpoint, err := newDeviceEndpoint(dev, mtu)
	if err != nil {
		return nil, err
	}
	if pcapFile != nil {
		endpoint, err = sniffer.NewWithWriter(endpoint, &pcapFileWrapper{pcapFile}, math.MaxUint32)
		if err != nil {
			return nil, err
		}
	}
	var o stack.Options
	if enableIPv6 {
		o = stack.Options{
			NetworkProtocols: []stack.NetworkProtocolFactory{
				ipv4.NewProtocol,
				ipv6.NewProtocol,
			},
			TransportProtocols: []stack.TransportProtocolFactory{
				tcp.NewProtocol,
				udp.NewProtocol,
				icmp.NewProtocol4,
				icmp.NewProtocol6,
			},
		}
	} else {
		o = stack.Options{
			NetworkProtocols: []stack.NetworkProtocolFactory{
				ipv4.NewProtocol,
			},
			TransportProtocols: []stack.TransportProtocolFactory{
				tcp.NewProtocol,
				udp.NewProtocol,
				icmp.NewProtocol4,
			},
		}
	}
	s := stack.New(o)
	s.SetRouteTable([]tcpip.Route{
		{
			Destination: header.IPv4EmptySubnet,
			NIC:         DefaultNIC,
		},
		{
			Destination: header.IPv6EmptySubnet,
			NIC:         DefaultNIC,
		},
	})

	bufSize := buf.Size
	s.SetTransportProtocolOption(tcp.ProtocolNumber, &tcpip.TCPReceiveBufferSizeRangeOption{
		Min:     1,
		Default: bufSize,
		Max:     bufSize,
	})
	s.SetTransportProtocolOption(tcp.ProtocolNumber, &tcpip.TCPSendBufferSizeRangeOption{
		Min:     1,
		Default: bufSize,
		Max:     bufSize,
	})

	sOpt := tcpip.TCPSACKEnabled(true)
	s.SetTransportProtocolOption(tcp.ProtocolNumber, &sOpt)

	mOpt := tcpip.TCPModerateReceiveBufferOption(true)
	s.SetTransportProtocolOption(tcp.ProtocolNumber, &mOpt)

	gTcpHandler(s, handler)
	gUdpHandler(s, handler)

	if discardIPv6 != nil || discardICMP {
		endpoint = &linkEndpointWithDiscard{
			LinkEndpoint: endpoint,
			discardIPv6:  discardIPv6,
			discardICMP:  discardICMP,
		}
	}

	if err := s.CreateNIC(DefaultNIC, endpoint); err != nil {
		return nil, errors.New(err.String())
	}
	if err := s.SetSpoofing(DefaultNIC, true); err != nil {
		return nil, errors.New(err.String())
	}
	if err := s.SetPromiscuousMode(DefaultNIC, true); err != nil {
		return nil, errors.New(err.String())
	}
	return &GVisor{
		endpoint: endpoint,
		stack:    s,
		pcapFile: pcapFile,
	}, nil
}

type pcapFileWrapper struct {
	io.Writer
}

func (w *pcapFileWrapper) Write(p []byte) (n int, err error) {
	return w.Writer.Write(p)
}
EOF

    prepend_line "//go:build linux" "$raw_work_dir/libexclavecore/nat/nat.go"
    cat << 'EOF' > "$raw_work_dir/libexclavecore/nat/nat_nonlinux.go"
//go:build !linux

package nat

import (
	"net/netip"
	"os"

	"github.com/exclavenetwork/exclave-core/v5/common/buf"
	"gvisor.dev/gvisor/pkg/tcpip"
	"gvisor.dev/gvisor/pkg/tcpip/header"
	"gvisor.dev/gvisor/pkg/tcpip/stack"

	"github.com/exclavenetwork/libexclavecore/tun"
)

var _ tun.Tun = (*SystemTun)(nil)

type SystemTun struct {
	dev          int32
	device       *os.File
	mtu          int32
	handler      tun.Handler
	addr4        netip.Addr
	addr6        netip.Addr
	enableIPv6   bool
	discardIPv6  func() bool
	discardICMP  bool
	tcpForwarder *tcpForwarder
}

func New(dev, mtu int32, handler tun.Handler, addr4, addr6 netip.Addr, enableIPv6, discardICMP bool, discardIPv6 func() bool) (*SystemTun, error) {
	t := &SystemTun{
		dev:         dev,
		device:      os.NewFile(uintptr(dev), "tun"),
		mtu:         mtu,
		handler:     handler,
		addr4:       addr4,
		addr6:       addr6,
		enableIPv6:  enableIPv6,
		discardIPv6: discardIPv6,
		discardICMP: discardICMP,
	}
	tcpForwarder, err := newTCPForwarder(t)
	if err != nil {
		return nil, err
	}
	t.tcpForwarder = tcpForwarder
	go t.dispatchLoop()
	return t, nil
}

func (t *SystemTun) dispatchLoop() {
	cache := buf.NewWithSize(t.mtu)
	defer func() {
		cache.Release()
	}()
	data := cache.Extend(cache.Cap())

	for {
		n, err := t.device.Read(data)
		if err != nil {
			break
		}
		cache.Clear()
		cache.Resize(0, int32(n))
		packet := data[:n]
		if t.deliverPacket(cache, packet) {
			cache = buf.NewWithSize(t.mtu)
			data = cache.Extend(cache.Cap())
		}
	}
}

func (t *SystemTun) writeRawPacket(pkt *stack.PacketBuffer) tcpip.Error {
	view := pkt.ToView()
	defer view.Release()
	_, err := t.device.Write(view.AsSlice())
	if err != nil {
		return &tcpip.ErrAborted{}
	}
	return nil
}

func (t *SystemTun) writeBuffer(bytes []byte) tcpip.Error {
	_, err := t.device.Write(bytes)
	if err != nil {
		return &tcpip.ErrAborted{}
	}
	return nil
}

func (t *SystemTun) deliverPacket(cache *buf.Buffer, packet []byte) bool {
	switch header.IPVersion(packet) {
	case header.IPv4Version:
		ipHdr := header.IPv4(packet)
		switch ipHdr.TransportProtocol() {
		case header.TCPProtocolNumber:
			t.tcpForwarder.processIPv4(ipHdr, ipHdr.Payload())
		case header.UDPProtocolNumber:
			t.processIPv4UDP(cache, ipHdr, ipHdr.Payload())
			return true
		case header.ICMPv4ProtocolNumber:
			if t.discardICMP {
				newError("discarded ICMP to ", ipHdr.DestinationAddress()).AtInfo().WriteToLog()
				return false
			}
			t.processICMPv4(ipHdr, ipHdr.Payload())
		}
	case header.IPv6Version:
		ipHdr := header.IPv6(packet)
		discardIPv6 := false
		if t.discardIPv6 != nil {
			discardIPv6 = t.discardIPv6()
		}
		switch ipHdr.TransportProtocol() {
		case header.TCPProtocolNumber:
			if discardIPv6 {
				newError("discarded IPv6 to ", ipHdr.DestinationAddress()).AtInfo().WriteToLog()
				return false
			}
			t.tcpForwarder.processIPv6(ipHdr, ipHdr.Payload())
		case header.UDPProtocolNumber:
			if discardIPv6 {
				newError("discarded IPv6 to ", ipHdr.DestinationAddress()).AtInfo().WriteToLog()
				return true
			}
			t.processIPv6UDP(cache, ipHdr, ipHdr.Payload())
			return true
		case header.ICMPv6ProtocolNumber:
			if discardIPv6 || t.discardICMP {
				newError("discarded ICMPv6 to ", ipHdr.DestinationAddress()).AtInfo().WriteToLog()
				return false
			}
			t.processICMPv6(ipHdr, ipHdr.Payload())
		}
	}
	return false
}

func (t *SystemTun) Close() error {
	t.tcpForwarder.Close()
	return nil
}
EOF
